fn update_place_ops_in_log_one_inductive(pre: Self, post: Self, node_id: NodeId, rid: ReqId) {
    assert forall |n| #[trigger] post.combiner.contains_key(n) implies post.wf_combiner_for_node_id(n) by {
        if n == node_id {
            assert(pre.combiner[n].is_Placed());
            let CombinerState::Placed { queued_ops } = pre.combiner[n];
            assert(post.combiner[n] == CombinerState::Placed { queued_ops: queued_ops.push(rid) });
            assert(post.local_updates.contains_key(rid));
            assert(post.local_updates[rid] == UpdateState::Placed { op: post.log[pre.tail].op, idx: pre.tail });
            assert(post.log == pre.log.insert(pre.tail, post.log[pre.tail]));
            LogRangeMatchesQueue_append(
                queued_ops,
                pre.log,
                post.log,
                0,
                pre.local_versions[n],
                pre.tail,
                n,
                pre.local_updates,
                post.local_updates,
                rid,
                post.log[pre.tail],
            );
        } else {
            assert(post.combiner[n] == pre.combiner[n]);
            assert(post.wf_combiner_for_node_id(n));
        }
    }

    assert forall |rid0| #[trigger] post.local_reads.contains_key(rid0)
        implies post.read_results_match(post.local_reads[rid0]) by {
        assert(pre.local_reads.contains_key(rid0));
        assert(post.local_reads[rid0] == pre.local_reads[rid0]);
        match post.local_reads[rid0] {
            ReadonlyState::Done { ret, version_upper_bound, op, .. } => {
                assert(exists |v: nat| rangeincl(version_upper_bound, v, pre.version_upper_bound)
                    && ret == DT::dispatch_spec(compute_nrstate_at_version(pre.log, v), op));
                let v = choose |v: nat| rangeincl(version_upper_bound, v, pre.version_upper_bound)
                    && ret == DT::dispatch_spec(compute_nrstate_at_version(pre.log, v), op);
                assert(forall |i| 0 <= i < v ==> pre.log.contains_key(i));
                assert(forall |i| 0 <= i < v ==> pre.log[i] == post.log[i]) by {
                    if 0 <= i < v {
                        assert(i < pre.tail);
                        assert(post.log[i] == pre.log[i]);
                    }
                }
                compute_nrstate_at_version_preserves(pre.log, post.log, v);
                assert(rangeincl(version_upper_bound, v, post.version_upper_bound));
            }
            _ => {}
        }
    }
}

